1	package filter
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/pkg/errors"
8	)
9	
10	type renderer struct {
11		schema             Schema
12		dialect            DialectName
13		placeholderOffset  int
14		placeholderCounter int
15		args               []any
16	}
17	
18	type renderResult struct {
19		sql           string
20		trivial       bool
21		unsatisfiable bool
22	}
23	
24	func newRenderer(schema Schema, opts RenderOptions) *renderer {
25		return &renderer{
26			schema:            schema,
27			dialect:           opts.Dialect,
28			placeholderOffset: opts.PlaceholderOffset,
29		}
30	}
31	
32	func (r *renderer) Render(cond Condition) (Statement, error) {
33		result, err := r.renderCondition(cond)
34		if err != nil {
35			return Statement{}, err
36		}
37		args := r.args
38		if args == nil {
39			args = []any{}
40		}
41	
42		switch {
43		case result.unsatisfiable:
44			return Statement{
45				SQL:  "1 = 0",
46				Args: args,
47			}, nil
48		case result.trivial:
49			return Statement{
50				SQL:  "",
51				Args: args,
52			}, nil
53		default:
54			return Statement{
55				SQL:  result.sql,
56				Args: args,
57			}, nil
58		}
59	}
60	
61	func (r *renderer) renderCondition(cond Condition) (renderResult, error) {
62		switch c := cond.(type) {
63		case *LogicalCondition:
64			return r.renderLogicalCondition(c)
65		case *NotCondition:
66			return r.renderNotCondition(c)
67		case *FieldPredicateCondition:
68			return r.renderFieldPredicate(c)
69		case *ComparisonCondition:
70			return r.renderComparison(c)
71		case *InCondition:
72			return r.renderInCondition(c)
73		case *ElementInCondition:
74			return r.renderElementInCondition(c)
75		case *TextMatchCondition:
76			return r.renderTextMatch(c)
77		case *RegexCondition:
78			return r.renderRegex(c)
79		case *ListComprehensionCondition:
80			return r.renderListComprehension(c)
81		case *ConstantCondition:
82			if c.Value {
83				return renderResult{trivial: true}, nil
84			}
85			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
86		default:
87			return renderResult{}, errors.Errorf("unsupported condition type %T", c)
88		}
89	}
90	
91	func (r *renderer) renderLogicalCondition(cond *LogicalCondition) (renderResult, error) {
92		left, err := r.renderCondition(cond.Left)
93		if err != nil {
94			return renderResult{}, err
95		}
96		right, err := r.renderCondition(cond.Right)
97		if err != nil {
98			return renderResult{}, err
99		}
100	
101		switch cond.Operator {
102		case LogicalAnd:
103			return combineAnd(left, right), nil
104		case LogicalOr:
105			return combineOr(left, right), nil
106		default:
107			return renderResult{}, errors.Errorf("unsupported logical operator %s", cond.Operator)
108		}
109	}
110	
111	func (r *renderer) renderNotCondition(cond *NotCondition) (renderResult, error) {
112		child, err := r.renderCondition(cond.Expr)
113		if err != nil {
114			return renderResult{}, err
115		}
116	
117		if child.trivial {
118			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
119		}
120		if child.unsatisfiable {
121			return renderResult{trivial: true}, nil
122		}
123		return renderResult{
124			sql: fmt.Sprintf("NOT (%s)", child.sql),
125		}, nil
126	}
127	
128	func (r *renderer) renderFieldPredicate(cond *FieldPredicateCondition) (renderResult, error) {
129		field, ok := r.schema.Field(cond.Field)
130		if !ok {
131			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
132		}
133	
134		switch field.Kind {
135		case FieldKindBoolColumn:
136			column := qualifyColumn(r.dialect, field.Column)
137			return renderResult{
138				sql: fmt.Sprintf("%s IS TRUE", column),
139			}, nil
140		case FieldKindJSONBool:
141			sql, err := r.jsonBoolPredicate(field)
142			if err != nil {
143				return renderResult{}, err
144			}
145			return renderResult{sql: sql}, nil
146		default:
147			return renderResult{}, errors.Errorf("field %q cannot be used as a predicate", cond.Field)
148		}
149	}
150	
151	func (r *renderer) renderComparison(cond *ComparisonCondition) (renderResult, error) {
152		switch left := cond.Left.(type) {
153		case *FieldRef:
154			field, ok := r.schema.Field(left.Name)
155			if !ok {
156				return renderResult{}, errors.Errorf("unknown field %q", left.Name)
157			}
158			switch field.Kind {
159			case FieldKindBoolColumn:
160				return r.renderBoolColumnComparison(field, cond.Operator, cond.Right)
161			case FieldKindJSONBool:
162				return r.renderJSONBoolComparison(field, cond.Operator, cond.Right)
163			case FieldKindScalar:
164				return r.renderScalarComparison(field, cond.Operator, cond.Right)
165			default:
166				return renderResult{}, errors.Errorf("field %q does not support comparison", field.Name)
167			}
168		case *FunctionValue:
169			return r.renderFunctionComparison(left, cond.Operator, cond.Right)
170		case *FieldAccessorValue:
171			return r.renderAccessorComparison(left, cond.Operator, cond.Right)
172		default:
173			return renderResult{}, errors.New("comparison must start with a field reference or supported function")
174		}
175	}
176	
177	// accessorSpec maps a CEL timestamp accessor to per-dialect SQL date-part tokens
178	// and the offset to subtract so the result matches CEL's base (e.g. CEL months
179	// are 0-based but every dialect reports 1-based, so off=1). off is indexed
180	// [sqlite, postgres, mysql].
181	type accessorSpec struct {
182		sqlite string // strftime format specifier
183		pg     string // EXTRACT field
184		mysql  string // function name
185		off    [3]int
186	}
187	
188	var accessorSpecs = map[string]accessorSpec{
189		"getFullYear":   {"%Y", "YEAR", "YEAR", [3]int{0, 0, 0}},
190		"getMonth":      {"%m", "MONTH", "MONTH", [3]int{1, 1, 1}},
191		"getDate":       {"%d", "DAY", "DAYOFMONTH", [3]int{0, 0, 0}},
192		"getDayOfMonth": {"%d", "DAY", "DAYOFMONTH", [3]int{1, 1, 1}},
193		"getDayOfWeek":  {"%w", "DOW", "DAYOFWEEK", [3]int{0, 0, 1}},
194		"getDayOfYear":  {"%j", "DOY", "DAYOFYEAR", [3]int{1, 1, 1}},
195		"getHours":      {"%H", "HOUR", "HOUR", [3]int{0, 0, 0}},
196		"getMinutes":    {"%M", "MINUTE", "MINUTE", [3]int{0, 0, 0}},
197		"getSeconds":    {"%S", "SECOND", "SECOND", [3]int{0, 0, 0}},
198	}
199	
200	func (r *renderer) renderAccessorComparison(acc *FieldAccessorValue, op ComparisonOperator, right ValueExpr) (renderResult, error) {
201		field, ok := r.schema.Field(acc.Field)
202		if !ok {
203			return renderResult{}, errors.Errorf("unknown field %q", acc.Field)
204		}
205		value, err := expectNumericLiteral(right)
206		if err != nil {
207			return renderResult{}, err
208		}
209		expr, err := r.timestampAccessorExpr(field, acc.Accessor)
210		if err != nil {
211			return renderResult{}, err
212		}
213		placeholder := r.addArg(value)
214		return renderResult{
215			sql: fmt.Sprintf("%s %s %s", expr, sqlOperator(op), placeholder),
216		}, nil
217	}
218	
219	// timestampAccessorExpr builds a dialect-specific integer expression for a CEL
220	// timestamp accessor. Extraction is UTC on SQLite/Postgres (epoch columns); on
221	// MySQL the TIMESTAMP column is read in the server session time zone.
222	func (r *renderer) timestampAccessorExpr(field Field, accessor string) (string, error) {
223		spec, ok := accessorSpecs[accessor]
224		if !ok {
225			return "", errors.Errorf("unsupported timestamp accessor %q", accessor)
226		}
227		col := qualifyColumn(r.dialect, field.Column)
228		var base string
229		var off int
230		switch r.dialect {
231		case DialectSQLite:
232			base = fmt.Sprintf("CAST(strftime('%s', %s, 'unixepoch') AS INTEGER)", spec.sqlite, col)
233			off = spec.off[0]
234		case DialectPostgres:
235			base = fmt.Sprintf("CAST(EXTRACT(%s FROM to_timestamp(%s) AT TIME ZONE 'UTC') AS INTEGER)", spec.pg, col)
236			off = spec.off[1]
237		case DialectMySQL:
238			base = fmt.Sprintf("%s(%s)", spec.mysql, col)
239			off = spec.off[2]
240		default:
241			return "", errors.Errorf("unsupported dialect %q", r.dialect)
242		}
243		if off != 0 {
244			base = fmt.Sprintf("(%s - %d)", base, off)
245		}
246		return base, nil
247	}
248	
249	func (r *renderer) renderFunctionComparison(fn *FunctionValue, op ComparisonOperator, right ValueExpr) (renderResult, error) {
250		if fn.Name != "size" {
251			return renderResult{}, errors.Errorf("unsupported function %s in comparison", fn.Name)
252		}
253		if len(fn.Args) != 1 {
254			return renderResult{}, errors.New("size() expects one argument")
255		}
256		fieldArg, ok := fn.Args[0].(*FieldRef)
257		if !ok {
258			return renderResult{}, errors.New("size() argument must be a field")
259		}
260	
261		field, ok := r.schema.Field(fieldArg.Name)
262		if !ok {
263			return renderResult{}, errors.Errorf("unknown field %q", fieldArg.Name)
264		}
265		if field.Kind == FieldKindVirtualAlias {
266			field, ok = r.schema.ResolveAlias(fieldArg.Name)
267			if !ok {
268				return renderResult{}, errors.Errorf("invalid alias %q", fieldArg.Name)
269			}
270		}
271	
272		value, err := expectNumericLiteral(right)
273		if err != nil {
274			return renderResult{}, err
275		}
276	
277		var expr string
278		switch {
279		case field.Kind == FieldKindJSONList:
280			expr = jsonArrayLengthExpr(r.dialect, field)
281		case field.Kind == FieldKindScalar && field.Type == FieldTypeString:
282			expr = stringLengthExpr(r.dialect, field.columnExpr(r.dialect))
283		default:
284			return renderResult{}, errors.Errorf("size() does not support field %q", field.Name)
285		}
286	
287		placeholder := r.addArg(value)
288		return renderResult{
289			sql: fmt.Sprintf("%s %s %s", expr, sqlOperator(op), placeholder),
290		}, nil
291	}
292	
293	// stringLengthExpr returns the character-count expression for a string column.
294	// MySQL's LENGTH counts bytes, so CHAR_LENGTH is used to count characters and
295	// match CEL's size() code-point semantics; SQLite/Postgres LENGTH already counts
296	// characters.
297	func stringLengthExpr(d DialectName, colExpr string) string {
298		if d == DialectMySQL {
299			return fmt.Sprintf("CHAR_LENGTH(%s)", colExpr)
300		}
301		return fmt.Sprintf("LENGTH(%s)", colExpr)
302	}
303	
304	func (r *renderer) renderScalarComparison(field Field, op ComparisonOperator, right ValueExpr) (renderResult, error) {
305		lit, err := expectLiteral(right)
306		if err != nil {
307			return renderResult{}, err
308		}
309	
310		columnExpr := field.columnExpr(r.dialect)
311		if lit == nil {
312			switch op {
313			case CompareEq:
314				return renderResult{sql: fmt.Sprintf("%s IS NULL", columnExpr)}, nil
315			case CompareNeq:
316				return renderResult{sql: fmt.Sprintf("%s IS NOT NULL", columnExpr)}, nil
317			default:
318				return renderResult{}, errors.Errorf("operator %s not supported for null comparison", op)
319			}
320		}
321	
322		placeholder := ""
323		switch field.Type {
324		case FieldTypeString:
325			value, ok := lit.(string)
326			if !ok {
327				return renderResult{}, errors.Errorf("field %q expects string value", field.Name)
328			}
329			placeholder = r.addArg(value)
330		case FieldTypeInt, FieldTypeTimestamp:
331			num, err := toInt64(lit)
332			if err != nil {
333				return renderResult{}, errors.Wrapf(err, "field %q expects integer value", field.Name)
334			}
335			placeholder = r.addArg(num)
336		default:
337			return renderResult{}, errors.Errorf("unsupported data type %q for field %s", field.Type, field.Name)
338		}
339	
340		return renderResult{
341			sql: fmt.Sprintf("%s %s %s", columnExpr, sqlOperator(op), placeholder),
342		}, nil
343	}
