357	func (r *renderer) renderJSONBoolComparison(field Field, op ComparisonOperator, right ValueExpr) (renderResult, error) {
358		value, err := expectBool(right)
359		if err != nil {
360			return renderResult{}, err
361		}
362	
363		jsonExpr := jsonExtractExpr(r.dialect, field)
364		switch r.dialect {
365		case DialectSQLite:
366			switch op {
367			case CompareEq:
368				if field.Name == "has_task_list" {
369					target := "0"
370					if value {
371						target = "1"
372					}
373					return renderResult{sql: fmt.Sprintf("%s = %s", jsonExpr, target)}, nil
374				}
375				if value {
376					return renderResult{sql: fmt.Sprintf("%s IS TRUE", jsonExpr)}, nil
377				}
378				return renderResult{sql: fmt.Sprintf("NOT(%s IS TRUE)", jsonExpr)}, nil
379			case CompareNeq:
380				if field.Name == "has_task_list" {
381					target := "0"
382					if value {
383						target = "1"
384					}
385					return renderResult{sql: fmt.Sprintf("%s != %s", jsonExpr, target)}, nil
386				}
387				if value {
388					return renderResult{sql: fmt.Sprintf("NOT(%s IS TRUE)", jsonExpr)}, nil
389				}
390				return renderResult{sql: fmt.Sprintf("%s IS TRUE", jsonExpr)}, nil
391			default:
392				return renderResult{}, errors.Errorf("operator %s not supported for boolean JSON field", op)
393			}
394		case DialectMySQL:
395			boolStr := "false"
396			if value {
397				boolStr = "true"
398			}
399			return renderResult{
400				sql: fmt.Sprintf("%s %s CAST('%s' AS JSON)", jsonExpr, sqlOperator(op), boolStr),
401			}, nil
402		case DialectPostgres:
403			placeholder := r.addArg(value)
404			return renderResult{
405				sql: fmt.Sprintf("(%s)::boolean %s %s", jsonExpr, sqlOperator(op), placeholder),
406			}, nil
407		default:
408			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
409		}
410	}
