558	func (r *renderer) renderRegex(cond *RegexCondition) (renderResult, error) {
559		field, ok := r.schema.Field(cond.Field)
560		if !ok {
561			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
562		}
563		column := field.columnExpr(r.dialect)
564		switch r.dialect {
565		case DialectPostgres:
566			// POSIX regex match operator.
567			return renderResult{sql: fmt.Sprintf("%s ~ %s", column, r.addArg(cond.Pattern))}, nil
568		case DialectMySQL, DialectSQLite:
569			// MySQL has a native REGEXP operator; SQLite uses the registered regexp() function.
570			return renderResult{sql: fmt.Sprintf("%s REGEXP %s", column, r.addArg(cond.Pattern))}, nil
571		default:
572			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
573		}
